/* token_map.h - from the PIF code (tokens.h) to the token number used by yacc
   Both the scanner (brainrot.l) and the PIF reader (brainrot.y) use it. */
#ifndef TOKEN_MAP_H
#define TOKEN_MAP_H
#include "tokens.h"
#include "brainrot.tab.h"      /* generated by bison -d: IDENTIFIER, NUMBER, PEIGENGOO, ... */

/* indexed by the PIF code; the entry of code 1 is not used, see yacc_token() */
static const int YACC_TOKEN[TOKEN_COUNT] = {
    IDENTIFIER, NUMBER,
    PEIGENGOO, GOJO_SATORU, SIXSEVEN, TRALALERO_TRALALA, CAPPUCCINO_ASSASSINO,
    HIPOCACTUS, BOMBOMBINI_GUSINI, TRIPPI_TROPPI, BOMBARDIRO_CROCODILO,
    TUNG_TUNG_TUNG_SAHUR, CHEESE_RATTATINO, SHPIONIRO_GOLUBIRO, CHIMPANZINI_BANANINI,
    EQ, NE, GT, LT, GE, LE,
    ASSIGN, PLUS, MINUS, ARROW, LPAREN, RPAREN, LBRACKET, RBRACKET,
    LBRACE, RBRACE, COMMA, COLON, DOT
};

/* the PIF has one code (1) for integer and string constants, but the grammar
   keeps <number> and <string> apart (as in v1.1), so the text decides: a
   string constant always starts with a quote, a number never does */
static int yacc_token(int code, const char *text) {
    if (code == T_CONSTANT) return text[0] == '"' ? STRING : NUMBER;
    return YACC_TOKEN[code];
}

#endif
